      <button
        {...a11yLabelProps}
        {...interactivePassthrough}
        {...describedByProp}
        ref={rootRef}
        type="button"
        data-avatar-item=""
        data-testid={testId}
        onClick={onClick}
        {...rootStylexProps}>
        {visualContent}
      </button>
    );
